void Platform_QueueAudio(const s16 *data, uint32_t bytesCount)
{
    if (headless) {
        return;
    }

    u32 queuedSize = SDL_GetQueuedAudioSize(1);




    if (queuedSize > (bytesCount * 10)) {
        SDL_ClearQueuedAudio(1);
        queuedSize = 0;
    }

    SDL_QueueAudio(1, data, bytesCount);
}

void Platform_ClearQueuedAudio(void)
{
    if (headless) {
        return;
    }
    SDL_ClearQueuedAudio(1);
}

void ProcessSDLEvents(void)
{
    SDL_Event event;

    while (SDL_PollEvent(&event)) {
        SDL_Keycode keyCode = event.key.keysym.sym;
        Uint16 keyMod = event.key.keysym.mod;

        switch (event.type) {
            case SDL_QUIT:
                isRunning = 0;
                break;
            case SDL_KEYUP:
                switch (event.key.keysym.sym) {
                    case SDLK_c: keys &= ~0x0001; break;
                    case SDLK_x: keys &= ~0x0002; break;
                    case SDLK_RETURN: keys &= ~0x0008; break;
                    case SDLK_BACKSLASH: keys &= ~0x0004; break;
                    case SDLK_s: keys &= ~0x0200; break;
                    case SDLK_d: keys &= ~0x0100; break;
                    case SDLK_UP: keys &= ~0x0040; break;
                    case SDLK_DOWN: keys &= ~0x0080; break;
                    case SDLK_LEFT: keys &= ~0x0020; break;
                    case SDLK_RIGHT: keys &= ~0x0010; break;
                    case SDLK_SPACE:
                        if (speedUp) {
                            speedUp = 0;
                            timeScale = 1.0;
                            SDL_ClearQueuedAudio(1);
                            SDL_PauseAudio(0);
                        }
                        break;
                }
                break;
            case SDL_KEYDOWN:
                if (keyCode == SDLK_RETURN && (keyMod & KMOD_ALT)) {
                    fullScreenFlags ^= SDL_WINDOW_FULLSCREEN_DESKTOP;
                    if (fullScreenFlags & SDL_WINDOW_FULLSCREEN_DESKTOP) {
                        SDL_GetWindowDisplayMode(sdlWindow, &sdlDispMode);
                        preFullscreenVideoScale = videoScale;
                    } else {
                        SDL_SetWindowDisplayMode(sdlWindow, &sdlDispMode);
                        videoScale = preFullscreenVideoScale;
                    }
                    SDL_SetWindowFullscreen(sdlWindow, fullScreenFlags);

                    SDL_SetWindowSize(sdlWindow, 320 * videoScale, 240 * videoScale);
                    videoScaleChanged = 0;
                } else
                    switch (event.key.keysym.sym) {
                        case SDLK_c: keys |= 0x0001; break;
                        case SDLK_x: keys |= 0x0002; break;
                        case SDLK_RETURN: keys |= 0x0008; break;
                        case SDLK_BACKSLASH: keys |= 0x0004; break;
                        case SDLK_s: keys |= 0x0200; break;
                        case SDLK_d: keys |= 0x0100; break;
                        case SDLK_UP: keys |= 0x0040; break;
                        case SDLK_DOWN: keys |= 0x0080; break;
                        case SDLK_LEFT: keys |= 0x0020; break;
                        case SDLK_RIGHT: keys |= 0x0010; break;
                        case SDLK_r:
                            if (event.key.keysym.mod & (KMOD_LCTRL | KMOD_RCTRL)) {
                                DoSoftReset();
                            }
                            break;
                        case SDLK_p:
                            if (event.key.keysym.mod & (KMOD_LCTRL | KMOD_RCTRL)) {
                                paused = !paused;
                            }
                            break;
                        case SDLK_SPACE:
                            if (!speedUp) {
                                speedUp = 1;
                                timeScale = 5.0f;
                                SDL_PauseAudio(1);
                            }
                            break;
                        case SDLK_F10:
                            paused = 1;
                            stepOneFrame = 1;
                            break;
                    }
                break;
            case SDL_CONTROLLERDEVICEADDED:
                if (!sdlGameController) {
                    sdlGameController = SDL_GameControllerOpen(event.cdevice.which);
                }
                break;
            case SDL_CONTROLLERDEVICEREMOVED:
                if (sdlGameController
                    && event.cdevice.which == SDL_JoystickInstanceID(SDL_GameControllerGetJoystick(sdlGameController))) {
                    SDL_GameControllerClose(sdlGameController);
                    sdlGameController = ((void*)0);
                }
                break;
            case SDL_WINDOWEVENT:
                if (event.window.event == SDL_WINDOWEVENT_SIZE_CHANGED) {
                    unsigned int w = event.window.data1;
                    unsigned int h = event.window.data2;

                    videoScale = 0;
                    if (w / 320 > videoScale)
                        videoScale = w / 320;
                    if (h / 240 > videoScale)
                        videoScale = h / 240;
                    if (videoScale < 1)
                        videoScale = 1;

                    videoScaleChanged = 1;
                }
                break;
        }
    }
}



static SharedKeys GetSDLGameControllerKeys(void)
{
    if (!sdlGameController) {
        return 0;
    }

    SharedKeys gcKeys = 0;

    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_A))
        gcKeys |= 0x0001;
    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_X))
        gcKeys |= 0x0002;
    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_START))
        gcKeys |= 0x0008;
    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_BACK))
        gcKeys |= 0x0004;
    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_LEFTSHOULDER))
        gcKeys |= 0x0200;
    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_RIGHTSHOULDER))
        gcKeys |= 0x0100;
    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_DPAD_UP))
        gcKeys |= 0x0040;
    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_DPAD_DOWN))
        gcKeys |= 0x0080;
    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_DPAD_LEFT))
        gcKeys |= 0x0020;
    if (SDL_GameControllerGetButton(sdlGameController, SDL_CONTROLLER_BUTTON_DPAD_RIGHT))
        gcKeys |= 0x0010;


    Sint16 xAxis = SDL_GameControllerGetAxis(sdlGameController, SDL_CONTROLLER_AXIS_LEFTX);
    Sint16 yAxis = SDL_GameControllerGetAxis(sdlGameController, SDL_CONTROLLER_AXIS_LEFTY);

    if (xAxis < -8000)
        gcKeys |= 0x0020;
    else if (xAxis > 8000)
        gcKeys |= 0x0010;
    if (yAxis < -8000)
        gcKeys |= 0x0040;
    else if (yAxis > 8000)
        gcKeys |= 0x0080;


    Sint16 rightTrigger = SDL_GameControllerGetAxis(sdlGameController, SDL_CONTROLLER_AXIS_TRIGGERRIGHT);
    if (rightTrigger > 20000)
        gcKeys |= (1 << 16);

    return gcKeys;
}

u16 Platform_GetKeyInput(void)
{
    SharedKeys gamepadKeys = GetSDLGameControllerKeys();







    speedUp = (gamepadKeys & (1 << 16)) ? 1 : 0;

    if (speedUp) {
        timeScale = 5.0f;
        SDL_PauseAudio(1);
    } else {
        timeScale = 1.0f;
        SDL_PauseAudio(0);
    }

    return (gamepadKeys != 0) ? (u16)(gamepadKeys & 0xFFFF) : keys;
}



