        WIN0right = ((((*(reg_wint *)(REG_BASE + (0x40 + sizeof(winreg_t) * 0)))) & 0x0000FFFF) >> 0);
        WIN0left = ((((*(reg_wint *)(REG_BASE + (0x40 + sizeof(winreg_t) * 0)))) & 0xFFFF0000) >> 16);



